it('reuses a registered schema across ten executions', async () => {
  const registry = new ToolRegistry();
  let schemaReads = 0;
  registry.register(
    {
      name: 'echo',
      description: 'Echo a location',
      get inputSchema() {
        schemaReads += 1;
        return {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
      },
    },
    async input => String(input.location)
  );

  const results = [];
  for (let call = 0; call < 10; call += 1) {
    results.push(await registry.execute('echo', {location: 'Berlin'}));
  }

  expect({schemaReads, results}).toEqual({schemaReads: 1, results: Array.from({length: 10}, () => ({result: 'Berlin'}))});
});
